-- Puan tahmini verileri (2026 sonuçları; LGS 2023–2025 katsayıları dahil). Kaynaklar: docs/PUAN_TAHMINI.md
on conflict (family,year) do update set base=excluded.base,coefs=excluded.coefs,question_counts=excluded.question_counts,means=excluded.means,source=excluded.source,notes=excluded.notes,updated_at=now();

on conflict do nothing;

on conflict (level,year,institution,program) do update set base_score=excluded.base_score,rank_value=excluded.rank_value,source=excluded.source;
